{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 GlobalTranspose (for Reaper)\par}
{\pard \ql \f0 \sa180 \li0 \fi0 2 JSFX Plugins:   midimaster - Belongs on master track  midislave - Belongs on an instrument track (before any instruments) \par}
{\pard \ql \f0 \sa180 \li0 \fi0 2 script:   masterkeybox - Changes the global key (requires midimaster to be on master track) supports mousewheel+dropbox.  addmasterslave - Adds midislave to selected track and adds midimaster to master track (if not found)\par}
{\pard \ql \f0 \sa180 \li0 \fi0  masterkeybox Requires ReaImGui (by cfillion)\par}
}
